  "check_code": "import sqlite3
from pathlib import Path


TARGET = "RMT-2025-017-003"
PROJECT = "AUD-NYIA-PI-2025-017"
VERIFY_AT = "2025-10-10T15:34:00+08:00"
DB_RELATIVE = Path("system") / "privacy_remediation_service_desk" / "state.db"


def _connect(ws):
    db_path = Path(ws).parent / DB_RELATIVE
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    return con


def _closure_event(con):
    return con.execute(
        """SELECT event_at FROM remediation_task_events
           WHERE task_id=? AND event_type=? AND event_at>?
             AND from_status=? AND to_status=? AND actor_id=?
           ORDER BY event_at DESC, task_event_id DESC LIMIT 1""",
        (TARGET, "verification_recorded", VERIFY_AT, "open", "closed", "OWN-AUDIT-001"),
    ).fetchone()


def check_target_closed(ws):
    with _connect(ws) as con:
        row = con.execute(
            "SELECT task_status FROM remediation_tasks WHERE task_id=? AND audit_project_id=?",
            (TARGET, PROJECT),
        ).fetchone()
    ok = row is not None and row["task_status"] == "closed"
    return {"score": 1 if ok else 0, "detail": "目标任务状态为 closed" if ok else "目标任务未处于 closed"}


def check_target_completed_at(ws):
    with _connect(ws) as con:
        row = con.execute(
            "SELECT completed_at FROM remediation_tasks WHERE task_id=? AND audit_project_id=?",
            (TARGET, PROJECT),
        ).fetchone()
        event = _closure_event(con)
    ok = (row is not None and row["completed_at"] is not None
          and event is not None and row["completed_at"] == event["event_at"])
    return {"score": 1 if ok else 0, "detail": "完成时间与实际关闭事件时间一致" if ok else "完成时间未与实际关闭事件关联"}


def check_target_due_date_preserved(ws):
    with _connect(ws) as con:
        row = con.execute(
            "SELECT due_date FROM remediation_tasks WHERE task_id=?",
            (TARGET,),
        ).fetchone()
    ok = row is not None and row["due_date"] == "2025-09-30"
    return {"score": 1 if ok else 0, "detail": "原整改期限保持不变" if ok else "原整改期限被修改或目标不存在"}


def check_closure_event(ws):
    with _connect(ws) as con:
        event = _closure_event(con)
        task = con.execute(
            "SELECT completed_at FROM remediation_tasks WHERE task_id=? AND audit_project_id=?",
            (TARGET, PROJECT),
        ).fetchone()
    ok = (event is not None and task is not None and task["completed_at"] is not None
          and task["completed_at"] == event["event_at"])
    return {"score": 1 if ok else 0, "detail": "存在 open 到 closed 的验证记录事件" if ok else "缺少符合条件的关闭事件"}


def check_other_current_tasks_unchanged(ws):
    expected = {
        "RMT-2025-017-001": ("closed", "2025-09-27T18:16:00+08:00", "2025-09-30"),
        "RMT-2025-017-002": ("closed", "2025-09-30T17:48:00+08:00", "2025-09-30"),
        "RMT-2025-017-004": ("closed", "2025-10-24T19:05:00+08:00", "2025-10-31"),
        "RMT-2025-017-005": ("in_verification", "2025-10-29T20:11:00+08:00", "2025-10-31"),
        "RMT-2025-017-006": ("closed", "2025-11-21T16:37:00+08:00", "2025-11-28"),
        "RMT-2025-017-007": ("open", None, "2025-11-28"),
    }
    with _connect(ws) as con:
        rows = con.execute(
            "SELECT task_id,task_status,completed_at,due_date FROM remediation_tasks WHERE audit_project_id=? AND task_id<>?",
            (PROJECT, TARGET),
        ).fetchall()
    actual = {row["task_id"]: (row["task_status"], row["completed_at"], row["due_date"]) for row in rows}
    ok = actual == expected
    return {"score": 1 if ok else 0, "detail": "其他当前项目任务未被改动" if ok else "其他当前项目任务存在状态、完成时间或期限变化"}
